28	/**
29	 * Install skills to a target directory.
30	 * Source may be tiered (atoms/, molecules/, compounds/) or flat.
31	 * Target is always flat (agent platforms expect flat user-level layout).
32	 */
33	export function installSkillsTo(
34	  sourceDir: string,
35	  targetDir: string,
36	  dryRun: boolean
37	): string[] {
38	  const installed: string[] = [];
39	  const tierDirs = ["atoms", "molecules", "compounds"];
40	
41	  if (!existsSync(sourceDir)) {
42	    return installed;
43	  }
44	
45	  function installEntry(src: string, name: string): void {
46	    const dest = resolve(targetDir, name);
47	    if (dryRun) {
48	      console.log(`  DRY-RUN: ${src} → ${dest}`);
49	    } else {
50	      mkdirSync(targetDir, { recursive: true });
51	      if (existsSync(dest)) {
52	        rmSync(dest, { recursive: true });
53	      }
54	      cpSync(src, dest, { recursive: true });
55	      console.log(`  Installed: ${name} → ${dest}`);
56	    }
57	    installed.push(name);
58	  }
59	
60	  // Scan tier subdirectories
61	  for (const tier of tierDirs) {
62	    const tierPath = resolve(sourceDir, tier);
63	    if (!existsSync(tierPath)) continue;
64	    const entries = readdirSync(tierPath, { withFileTypes: true });
65	    for (const entry of entries) {
66	      if (!entry.isDirectory()) continue;
67	      installEntry(resolve(tierPath, entry.name), entry.name);
68	    }
69	  }
70	
71	  // Scan root for flat skills (backward compat)
72	  const entries = readdirSync(sourceDir, { withFileTypes: true });
73	  for (const entry of entries) {
74	    if (!entry.isDirectory()) continue;
75	    if (tierDirs.includes(entry.name)) continue;
76	    installEntry(resolve(sourceDir, entry.name), entry.name);
77	  }
78	
79	  return installed;
80	}
