5	export function createValidateCommand(): Command {
6	  const cmd = new Command("validate");
7	
8	  cmd
9	    .description(
10	      "Validate all skills structure and constraints (meta schema, SKILL.md, slug match, tier rules)"
11	    )
12	    .option("--path <dir>", "Skills root directory to validate", ".")
13	    .action((opts) => {
14	      const rootDir = resolve(opts.path);
15	
16	      // Find skills in known locations
17	      const searchPaths = [
18	        resolve(rootDir, ".opencode/skills"),
19	        resolve(rootDir, ".claude/skills"),
20	        resolve(rootDir, ".codex/skills"),
21	      ];
22	
23	      let skillsDir: string | null = null;
24	      for (const p of searchPaths) {
25	        const skills = discoverSkills(p);
26	        if (skills.length > 0) {
27	          skillsDir = p;
28	          break;
29	        }
30	      }
31	
32	      if (!skillsDir) {
33	        // Try the path itself as a skills directory
34	        const directSkills = discoverSkills(rootDir);
35	        if (directSkills.length > 0) {
36	          skillsDir = rootDir;
37	        }
38	      }
39	
40	      if (!skillsDir) {
41	        console.error(
42	          `No skills found in ${rootDir} or its .opencode/skills/, .claude/skills/, .codex/skills/ subdirectories.`
43	        );
44	        process.exit(1);
45	      }
46	
47	      const skills = discoverSkills(skillsDir);
48	      console.log(`Validating ${skills.length} skill(s) in ${skillsDir}\n`);
49	
50	      // Find schemas directory for validation
51	      const schemasDir = resolve(rootDir, "schemas");
52	      const issues = validateAllSkills(
53	        skillsDir,
54	        schemasDir
55	      );
56	
57	      if (issues.length === 0) {
58	        console.log(`All ${skills.length} skills valid.`);
59	        process.exit(0);
60	      } else {
61	        for (const issue of issues) {
62	          console.error(`\n${issue.slug}:`);
63	          for (const msg of issue.issues) {
64	            console.error(`  - ${msg}`);
65	          }
66	        }
67	        console.error(
68	          `\n${issues.length} skill(s) with issues, ${skills.length - issues.length} valid.`
69	        );
70	        process.exit(1);
71	      }
72	    });
73	
74	  return cmd;
75	}
