11	/**
12	 * List active changes in openspec/changes/.
13	 */
14	function listChanges(cwd: string, json: boolean): void {
15	  const changesDir = resolve(cwd, "openspec/changes");
16	  if (!existsSync(changesDir)) {
17	    if (json) {
18	      console.log(JSON.stringify([]));
19	    } else {
20	      console.log("No changes found.");
21	    }
22	    return;
23	  }
24	
25	  const entries = readdirSync(changesDir, { withFileTypes: true });
26	  const changes: Array<{
27	    name: string;
28	    lastModified: string;
29	    completedTasks: number;
30	    totalTasks: number;
31	  }> = [];
32	
33	  for (const entry of entries) {
34	    if (!entry.isDirectory()) continue;
35	    const changeDir = resolve(changesDir, entry.name);
36	    const tasksPath = resolve(changeDir, "tasks.md");
37	
38	    let completedTasks = 0;
39	    let totalTasks = 0;
40	
41	    if (existsSync(tasksPath)) {
42	      const content = readFileSync(tasksPath, "utf-8");
43	      const lines = content.split("\n");
44	      for (const line of lines) {
45	        if (/^\s*- \[[ x]\]/.test(line)) {
46	          totalTasks++;
47	          if (/^\s*- \[x\]/.test(line)) {
48	            completedTasks++;
49	          }
50	        }
51	      }
52	    }
53	
54	    const stat = statSync(changeDir);
55	
56	    changes.push({
57	      name: entry.name,
58	      lastModified: stat.mtime.toISOString(),
59	      completedTasks,
60	      totalTasks,
61	    });
62	  }
63	
64	  if (json) {
65	    console.log(JSON.stringify(changes, null, 2));
66	  } else {
67	    if (changes.length === 0) {
68	      console.log("No changes found.");
69	      return;
70	    }
71	    console.log("Changes:\n");
72	    for (const change of changes) {
73	      const pct =
74	        change.totalTasks > 0
75	          ? Math.round((change.completedTasks / change.totalTasks) * 100)
76	          : 0;
77	      console.log(
78	        `  ${change.name}  ${change.completedTasks}/${change.totalTasks} tasks (${pct}%)  modified: ${change.lastModified.split("T")[0]}`
79	      );
80	    }
81	  }
82	}
