93	    resolve(cwd, ".opencode/skills"),
94	    resolve(cwd, ".claude/skills"),
95	    resolve(cwd, ".codex/skills"),
96	    resolve(cwd, "assets/skills"), // bundled
97	  ];
98	
99	  let skills = [];
100	  for (const p of searchPaths) {
101	    const found = discoverSkills(p);
102	    if (found.length > 0) {
103	      skills = found;
104	      break;
105	    }
106	  }
107	
108	  if (skills.length === 0) {
109	    if (opts.json) {
110	      console.log(JSON.stringify([]));
111	    } else {
112	      console.log("No skills found.");
113	    }
114	    return;
115	  }
116	
117	  // Apply filters
118	  const filtered = filterSkills(skills, {
119	    tier: opts.tier as SkillTier | undefined,
120	    platform: opts.platform as SkillPlatform | undefined,
121	  });
122	
123	  if (opts.json) {
124	    const output = filtered.map((s) => ({
125	      slug: s.slug,
126	      tier: s.meta.tier,
127	      platform: s.meta.platform,
128	      version: s.meta.version,
129	      description: s.meta.description,
130	      depends_on: s.meta.depends_on,
131	    }));
132	    console.log(JSON.stringify(output, null, 2));
133	  } else {
134	    console.log(`Skills (${filtered.length}):\n`);
135	    for (const s of filtered) {
136	      console.log(
137	        `  ${s.slug}  [${s.meta.tier}/${s.meta.platform}]  ${s.meta.description}`
138	      );
139	    }
140	  }
141	}
