10	/**
11	 * Generate a Mermaid flowchart from skill dependencies.
12	 */
13	function toMermaid(skills: DiscoveredSkill[]): string {
14	  const lines: string[] = ["graph TD"];
15	
16	  // Add nodes with tier styling
17	  for (const skill of skills) {
18	    const label = `${skill.slug}`;
19	    lines.push(`  ${skill.slug}["${label}"]`);
20	  }
21	
22	  // Add edges for dependencies
23	  for (const skill of skills) {
24	    for (const dep of skill.meta.depends_on) {
25	      // Only add edge if dep is in the filtered set
26	      if (skills.some((s) => s.slug === dep)) {
27	        lines.push(`  ${dep} --> ${skill.slug}`);
28	      }
29	    }
30	  }
31	
32	  // Add tier class definitions
33	  lines.push("");
34	  lines.push("  classDef atom fill:#e8f5e9,stroke:#4caf50");
35	  lines.push("  classDef molecule fill:#e3f2fd,stroke:#2196f3");
36	  lines.push("  classDef compound fill:#fce4ec,stroke:#e91e63");
37	
38	  // Apply classes
39	  const atoms = skills.filter((s) => s.meta.tier === "atom").map((s) => s.slug);
40	  const molecules = skills
41	    .filter((s) => s.meta.tier === "molecule")
42	    .map((s) => s.slug);
43	  const compounds = skills
44	    .filter((s) => s.meta.tier === "compound")
45	    .map((s) => s.slug);
46	
47	  if (atoms.length > 0) lines.push(`  class ${atoms.join(",")} atom`);
48	  if (molecules.length > 0)
49	    lines.push(`  class ${molecules.join(",")} molecule`);
50	  if (compounds.length > 0)
51	    lines.push(`  class ${compounds.join(",")} compound`);
52	
53	  return lines.join("\n");
54	}
55	
56	/**
57	 * Generate a Graphviz DOT graph from skill dependencies.
58	 */
59	function toDot(skills: DiscoveredSkill[]): string {
60	  const lines: string[] = ["digraph skills {"];
61	  lines.push("  rankdir=BT;");
62	  lines.push("  node [shape=box, style=filled];");
63	  lines.push("");
64	
65	  // Tier-based colors
66	  const tierColors: Record<string, string> = {
67	    atom: "#e8f5e9",
68	    molecule: "#e3f2fd",
69	    compound: "#fce4ec",
70	  };
71	
72	  // Add nodes
73	  for (const skill of skills) {
74	    const color = tierColors[skill.meta.tier] || "#ffffff";
75	    lines.push(
76	      `  "${skill.slug}" [label="${skill.slug}\\n(${skill.meta.tier})", fillcolor="${color}"];`
77	    );
78	  }
79	
80	  lines.push("");
81	
82	  // Add edges
83	  for (const skill of skills) {
84	    for (const dep of skill.meta.depends_on) {
85	      if (skills.some((s) => s.slug === dep)) {
86	        lines.push(`  "${dep}" -> "${skill.slug}";`);
87	      }
88	    }
89	  }
90	
91	  lines.push("}");
92	  return lines.join("\n");
93	}
