112	      ];
113	
114	      let allSkills: DiscoveredSkill[] = [];
115	      for (const p of searchPaths) {
116	        const found = discoverSkills(p);
117	        if (found.length > 0) {
118	          allSkills = found;
119	          break;
120	        }
121	      }
122	
123	      // Also try the path directly as a skills dir
124	      if (allSkills.length === 0) {
125	        allSkills = discoverSkills(rootDir);
126	      }
127	
128	      if (allSkills.length === 0) {
129	        console.error("No skills found.");
