65	function checkNodeVersion(): CheckResult {
66	  const version = process.versions.node;
67	  const major = parseInt(version.split(".")[0]!, 10);
68	
69	  if (major >= 18) {
70	    return {
71	      name: "Node.js",
72	      passed: true,
73	      message: `v${version}`,
74	    };
75	  }
76	
77	  return {
78	    name: "Node.js",
79	    passed: false,
80	    message: `v${version} (requires >= 18)`,
81	    suggestion: "Upgrade Node.js to version 18 or later.",
82	  };
83	}
84	
85	function checkSkillDirs(): CheckResult[] {
86	  const results: CheckResult[] = [];
87	  const home = homedir();
88	
89	  const dirs = [
90	    { name: "~/.claude/skills/", path: resolve(home, ".claude/skills") },
91	    {
92	      name: "~/.config/opencode/skill/",
93	      path: resolve(home, ".config/opencode/skill"),
94	    },
95	  ];
96	
97	  for (const dir of dirs) {
98	    if (!existsSync(dir.path)) {
99	      results.push({
100	        name: dir.name,
101	        passed: false,
102	        message: "not found",
103	        suggestion: `Run \`corgispec install\` to create.`,
104	      });
105	    } else {
106	      // Check writable
107	      try {
108	        accessSync(dir.path, constants.W_OK);
109	        results.push({
110	          name: dir.name,
111	          passed: true,
112	          message: "exists and writable",
113	        });
114	      } catch {
115	        results.push({
116	          name: dir.name,
117	          passed: false,
118	          message: "exists but not writable",
119	          suggestion: `Check permissions on ${dir.path}`,
120	        });
121	      }
122	    }
123	  }
124	
125	  return results;
126	}
