182	function checkSchemas(cwd: string): CheckResult {
183	  // Check project schemas first, then bundled schemas
184	  const schemaDirs = [
185	    resolve(cwd, "openspec/schemas"),
186	    resolve(import.meta.dirname ?? ".", "../assets/schemas"),
187	    resolve(import.meta.dirname ?? ".", "../../assets/schemas"),
188	  ];
189	
190	  let schemasDir: string | null = null;
191	  for (const dir of schemaDirs) {
192	    if (existsSync(dir)) {
193	      schemasDir = dir;
194	      break;
195	    }
196	  }
197	
198	  if (!schemasDir) {
199	    return {
200	      name: "Schemas",
201	      passed: true, // Not a hard failure if no schemas available
202	      message: "no schemas directory found",
203	    };
204	  }
205	
206	  try {
207	    const entries = readdirSync(schemasDir, { withFileTypes: true });
208	    const schemaDirNames = entries
209	      .filter((e) => e.isDirectory())
210	      .map((e) => e.name);
211	
212	    let validCount = 0;
213	    const errors: string[] = [];
214	
215	    for (const name of schemaDirNames) {
216	      const schemaFile = resolve(schemasDir, name, "schema.yaml");
217	      if (!existsSync(schemaFile)) {
218	        errors.push(`${name}/schema.yaml missing`);
219	        continue;
220	      }
221	
222	      try {
223	        const content = readFileSync(schemaFile, "utf-8");
224	        const parsed = yaml.load(content) as Record<string, unknown> | null;
225	
226	        // Validate required schema structure
227	        if (!parsed || typeof parsed !== "object") {
228	          errors.push(`${name}/schema.yaml is not a valid YAML document`);
229	          continue;
230	        }
231	
232	        if (!parsed.name || typeof parsed.name !== "string") {
233	          errors.push(`${name}/schema.yaml missing required 'name' field`);
234	          continue;
235	        }
236	
237	        if (!parsed.artifacts || !Array.isArray(parsed.artifacts)) {
238	          errors.push(`${name}/schema.yaml missing required 'artifacts' array`);
239	          continue;
240	        }
241	
242	        validCount++;
243	      } catch (parseErr: unknown) {
244	        const msg = parseErr instanceof Error ? parseErr.message : String(parseErr);
245	        errors.push(`${name}/schema.yaml is not valid YAML: ${msg}`);
246	      }
247	    }
248	
249	    if (errors.length > 0) {
250	      return {
251	        name: "Schemas",
252	        passed: false,
253	        message: errors.join("; "),
254	        suggestion: "Reinstall or repair schema files.",
255	      };
256	    }
257	
258	    return {
259	      name: "Schemas",
260	      passed: true,
261	      message: `${validCount} schema(s) valid`,
262	    };
263	  } catch (err: unknown) {
264	    const msg = err instanceof Error ? err.message : String(err);
265	    return {
266	      name: "Schemas",
267	      passed: false,
268	      message: msg,
269	      suggestion: "Check schema directory permissions.",
270	    };
271	  }
272	}
273	
274	function checkHooks(cwd: string): CheckResult {
275	  const hookStatus = detectHookConfig(cwd);
276	
277	  if (hookStatus.configured) {
278	    return {
279	      name: "Hooks",
280	      passed: true,
281	      message: `configured for ${hookStatus.platform} (${hookStatus.events.join(", ")})`,
282	    };
283	  }
284	
285	  return {
286	    name: "Hooks",
287	    passed: true,
288	    message: "not configured",
289	    suggestion: "Run `corgispec hooks generate --platform <name>` to enable hooks.",
290	  };
291	}
292	
293	function printResults(results: CheckResult[]): void {
294	  console.log("corgispec doctor\n");
295	
296	  let passCount = 0;
297	  let failCount = 0;
298	
299	  for (const r of results) {
300	    const icon = r.passed ? "✓" : "✗";
301	    const status = r.passed ? "pass" : "FAIL";
302	    console.log(`  ${icon} ${r.name}: ${r.message} (${status})`);
303	    if (!r.passed && r.suggestion) {
304	      console.log(`    → ${r.suggestion}`);
305	    }
306	    if (r.passed) passCount++;
307	    else failCount++;
308	  }
309	
310	  console.log();
311	  if (failCount === 0) {
312	    console.log(`All ${passCount} checks passed.`);
313	  } else {
314	    console.log(
315	      `${passCount} passed, ${failCount} failed.`
316	    );
317	  }
318	}
