6	export function createArchiveCommand(): Command {
7	  const cmd = new Command("archive")
8	    .description("Check completeness and output archive instructions")
9	    .argument("[name]", "Change name (auto-selects if only one exists)")
10	    .option("--json", "Output as JSON")
11	    .option("--path <dir>", "Working directory", ".")
12	    .action((name: string | undefined, opts: { json?: boolean; path: string }) => {
13	      try {
14	        const cwd = resolve(opts.path);
15	
16	        let changeName = name;
17	        if (!changeName) {
18	          const changes = discoverChanges(cwd);
19	          if (changes.length === 1) {
20	            changeName = changes[0]!;
21	          } else if (changes.length === 0) {
22	            console.error("Error: No changes found.");
23	            process.exit(1);
24	          } else {
25	            console.error(
26	              "Error: Multiple changes found. Specify one:\n" +
27	                changes.map((c) => `  - ${c}`).join("\n")
28	            );
29	            process.exit(1);
30	          }
31	        }
32	
33	        const result = resolveArchiveInstruction(cwd, changeName);
34	
35	        if (!result.isReady) {
36	          console.error(result.reason ?? "Change not ready for archive");
37	          process.exit(1);
38	        }
39	
40	        if (opts.json) {
41	          console.log(JSON.stringify(result, null, 2));
42	        } else {
43	          console.log(`Archive: ${result.changeName}\n`);
44	          console.log(result.instruction);
45	          console.log("\nContext files:");
46	          for (const f of result.contextFiles) {
47	            console.log(`  - ${f}`);
48	          }
49	        }
50	      } catch (err: unknown) {
51	        const msg = err instanceof Error ? err.message : String(err);
52	        console.error(`Error: ${msg}`);
53	        process.exit(1);
54	      }
55	    });
56	
57	  return cmd;
58	}
