80	/**
81	 * Load the active workflow schema based on config.yaml.
82	 */
83	export function loadWorkflowSchema(cwd: string): WorkflowSchema {
84	  const config = loadConfigFromDir(cwd);
85	  const schemaName = config.schema;
86	  const schemaPath = resolve(cwd, "openspec/schemas", schemaName, "schema.yaml");
87	
88	  if (!existsSync(schemaPath)) {
89	    throw new Error(
90	      `Schema '${schemaName}' not found at ${schemaPath}. Check openspec/config.yaml.`
91	    );
92	  }
93	
94	  const raw = readFileSync(schemaPath, "utf-8");
95	  const schema = yaml.load(raw) as WorkflowSchema;
96	
97	  // Ensure all artifacts have requires array
98	  for (const artifact of schema.artifacts) {
99	    if (!artifact.requires) {
100	      artifact.requires = [];
101	    }
102	  }
103	
104	  return schema;
105	}
