126	// ─── Change Discovery ───────────────────────────────────────────────────
127	
128	/**
129	 * Discover all active changes in openspec/changes/.
130	 */
131	export function discoverChanges(cwd: string): string[] {
132	  const changesDir = resolve(cwd, "openspec/changes");
133	  if (!existsSync(changesDir)) {
134	    return [];
135	  }
136	
137	  return readdirSync(changesDir, { withFileTypes: true })
138	    .filter((e) => e.isDirectory())
139	    .map((e) => e.name);
140	}
141	
142	/**
143	 * Check if an artifact file exists for a given change.
144	 */
145	function artifactExists(changeDir: string, generates: string): boolean {
146	  if (generates.includes("*")) {
147	    // Glob pattern like "specs/**/*.md" — check if directory has any files
148	    const baseDir = generates.split("/")[0]!;
149	    const dir = resolve(changeDir, baseDir);
150	    if (!existsSync(dir)) return false;
151	
152	    // Recursively check for .md files
153	    return hasMarkdownFiles(dir);
154	  }
155	
156	  return existsSync(resolve(changeDir, generates));
157	}
158	
159	function hasMarkdownFiles(dir: string): boolean {
160	  const entries = readdirSync(dir, { withFileTypes: true });
161	  for (const entry of entries) {
162	    if (entry.isFile() && entry.name.endsWith(".md")) return true;
163	    if (entry.isDirectory()) {
164	      if (hasMarkdownFiles(resolve(dir, entry.name))) return true;
165	    }
166	  }
167	  return false;
168	}
