57	/**
58	 * Generate instruction JSON for creating a specific artifact.
59	 */
60	export function resolveArtifactInstruction(
61	  cwd: string,
62	  changeName: string,
63	  artifactId: string
64	): ArtifactInstruction {
65	  const schema = loadWorkflowSchema(cwd);
66	  const config = loadConfigFromDir(cwd);
67	  const changeInfo = getChangeInfo(cwd, changeName);
68	  const changeDir = resolve(cwd, "openspec/changes", changeName);
69	
70	  // Find the artifact definition
71	  const artifact = schema.artifacts.find((a) => a.id === artifactId);
72	  if (!artifact) {
73	    const validIds = schema.artifacts.map((a) => a.id).join(", ");
74	    throw new Error(
75	      `Unknown artifact '${artifactId}'. Valid artifacts: ${validIds}`
76	    );
77	  }
78	
79	  // Check if blocked
80	  const status = changeInfo.artifacts.find((a) => a.id === artifactId);
81	  if (status?.blocked) {
82	    throw new Error(
83	      `Artifact '${artifactId}' is blocked. Missing: ${status.blockedBy.join(", ")}`
84	    );
85	  }
86	
87	  // Load template
88	  const template = loadTemplate(cwd, schema.name, artifact.template);
89	
90	  // Determine output path
91	  const outputPath = resolve(changeDir, artifact.generates);
92	
93	  // Gather context files (existing artifacts that this one depends on)
94	  const contextFiles = gatherContextFiles(changeDir, artifact.requires, schema);
95	
96	  // Get per-artifact rules
97	  const rules = getArtifactRules(config, artifactId);
98	
99	  return {
100	    changeName,
101	    artifactId,
102	    template,
103	    instruction: artifact.instruction,
104	    outputPath,
105	    dependencies: artifact.requires,
106	    contextFiles,
107	    projectContext: config.context ?? "",
108	    rules,
109	  };
110	}
