2	import { resolve } from "node:path";
3	import yaml from "js-yaml";
4	
5	/**
6	 * Supported schema types.
7	 */
8	export type SchemaType = "gitlab-tracked" | "github-tracked";
9	
10	/**
11	 * Isolation mode configuration.
12	 */
13	export interface IsolationConfig {
14	  mode: "worktree" | "none";
15	  root?: string;
16	  branch_prefix?: string;
17	}
18	
19	/**
20	 * Per-artifact rule lists.
21	 */
22	export interface RulesConfig {
23	  [artifactId: string]: string[];
24	}
25	
26	/**
27	 * The parsed and validated Corgi config.
28	 */
29	export interface OpenSpecConfig {
30	  schema: SchemaType;
31	  isolation?: IsolationConfig;
32	  context?: string;
33	  rules?: RulesConfig;
34	}
35	
36	/**
37	 * Raw shape of config.yaml before validation.
38	 */
39	interface RawConfig {
40	  schema?: unknown;
41	  isolation?: unknown;
42	  context?: unknown;
43	  rules?: unknown;
44	}
45	
46	export class ConfigError extends Error {
47	  constructor(message: string) {
48	    super(message);
49	    this.name = "ConfigError";
50	  }
51	}
52	
53	const VALID_SCHEMAS: SchemaType[] = ["gitlab-tracked", "github-tracked"];
54	const VALID_ISOLATION_MODES = ["worktree", "none"] as const;
55	
56	/**
57	 * Find and read the openspec/config.yaml file starting from a given directory.
58	 * Looks for `openspec/config.yaml` relative to `cwd`.
59	 */
60	export function findConfigPath(cwd: string): string | null {
61	  const configPath = resolve(cwd, "openspec/config.yaml");
62	  if (existsSync(configPath)) {
63	    return configPath;
64	  }
65	  return null;
66	}
67	
68	/**
69	 * Load and validate the Corgi config from a file path.
70	 * Throws ConfigError if the file is missing, unparseable, or invalid.
71	 */
72	export function loadConfig(configPath: string): OpenSpecConfig {
73	  if (!existsSync(configPath)) {
74	    throw new ConfigError(`Config file not found: ${configPath}`);
75	  }
76	
77	  let raw: unknown;
78	  try {
79	    const content = readFileSync(configPath, "utf-8");
80	    raw = yaml.load(content);
81	  } catch (err) {
82	    throw new ConfigError(
83	      `Failed to parse config YAML: ${err instanceof Error ? err.message : String(err)}`
84	    );
85	  }
86	
87	  if (raw === null || raw === undefined || typeof raw !== "object") {
88	    throw new ConfigError("Config file is empty or not a YAML mapping");
89	  }
90	
91	  return validateConfig(raw as RawConfig);
92	}
93	
94	/**
95	 * Load config from a working directory (convenience wrapper).
96	 */
97	export function loadConfigFromDir(cwd: string): OpenSpecConfig {
98	  const configPath = findConfigPath(cwd);
99	  if (!configPath) {
100	    throw new ConfigError(
101	      `No openspec/config.yaml found in ${cwd}. Run 'corgispec init' to set up.`
102	    );
103	  }
104	  return loadConfig(configPath);
105	}
106	
107	/**
108	 * Validate raw parsed YAML against the config schema.
109	 */
110	function validateConfig(raw: RawConfig): OpenSpecConfig {
111	  // schema: required
112	  if (!raw.schema) {
113	    throw new ConfigError("Missing required field: 'schema'");
114	  }
115	  if (typeof raw.schema !== "string") {
116	    throw new ConfigError(`Field 'schema' must be a string, got ${typeof raw.schema}`);
117	  }
118	  if (!VALID_SCHEMAS.includes(raw.schema as SchemaType)) {
119	    throw new ConfigError(
120	      `Unsupported schema '${raw.schema}'. Supported: ${VALID_SCHEMAS.join(", ")}`
121	    );
122	  }
123	
124	  const config: OpenSpecConfig = {
125	    schema: raw.schema as SchemaType,
126	  };
127	
128	  // isolation: optional
129	  if (raw.isolation !== undefined && raw.isolation !== null) {
130	    if (typeof raw.isolation !== "object") {
131	      throw new ConfigError("Field 'isolation' must be a mapping");
132	    }
133	    const iso = raw.isolation as Record<string, unknown>;
134	
135	    if (!iso.mode || typeof iso.mode !== "string") {
136	      throw new ConfigError("Field 'isolation.mode' is required when isolation is specified");
137	    }
138	    if (!VALID_ISOLATION_MODES.includes(iso.mode as (typeof VALID_ISOLATION_MODES)[number])) {
139	      throw new ConfigError(
140	        `Invalid isolation.mode '${iso.mode}'. Supported: ${VALID_ISOLATION_MODES.join(", ")}`
141	      );
142	    }
143	
144	    config.isolation = {
145	      mode: iso.mode as "worktree" | "none",
146	      root: typeof iso.root === "string" ? iso.root : undefined,
147	      branch_prefix: typeof iso.branch_prefix === "string" ? iso.branch_prefix : undefined,
148	    };
149	  }
150	
151	  // context: optional string
152	  if (raw.context !== undefined && raw.context !== null) {
153	    if (typeof raw.context !== "string") {
154	      throw new ConfigError("Field 'context' must be a string");
155	    }
156	    config.context = raw.context;
157	  }
158	
159	  // rules: optional mapping of string[]
160	  if (raw.rules !== undefined && raw.rules !== null) {
161	    if (typeof raw.rules !== "object") {
162	      throw new ConfigError("Field 'rules' must be a mapping");
163	    }
164	    const rulesRaw = raw.rules as Record<string, unknown>;
165	    const rules: RulesConfig = {};
166	    for (const [key, value] of Object.entries(rulesRaw)) {
167	      if (!Array.isArray(value)) {
168	        throw new ConfigError(`Field 'rules.${key}' must be an array of strings`);
169	      }
170	      rules[key] = value.map((v) => String(v));
171	    }
172	    config.rules = rules;
173	  }
174	
175	  return config;
176	}
