91	    } catch (err) {
92	      throw new SchemaError(
93	        `Failed to compile schema '${filename}': ${err instanceof Error ? err.message : String(err)}`
94	      );
95	    }
96	
97	    this.validators.set(filename, validator);
98	    return validator;
99	  }
100	
101	  /**
102	   * Validate data against a named schema.
103	   */
104	  validate(schemaFilename: string, data: unknown): ValidationResult {
105	    const validator = this.loadSchema(schemaFilename);
106	    const valid = validator(data) as boolean;
107	    return {
108	      valid,
109	      errors: valid ? undefined : (validator.errors ?? undefined),
110	    };
111	  }
112	
113	  /**
114	   * Check if all bundled schemas are valid JSON Schema documents.
115	   * Returns an array of { filename, error } for any that fail.
116	   */
117	  validateAllSchemas(): Array<{ filename: string; error?: string }> {
118	    const results: Array<{ filename: string; error?: string }> = [];
119	    const schemas = this.listSchemas();
120	
121	    for (const filename of schemas) {
122	      try {
123	        this.loadSchema(filename);
124	        results.push({ filename });
125	      } catch (err) {
126	        results.push({
127	          filename,
128	          error: err instanceof Error ? err.message : String(err),
129	        });
130	      }
131	    }
132	
133	    return results;
134	  }
135	}
