92	/**
93	 * Format session context as the standardized additionalContext Markdown string.
94	 */
95	export function formatContextMarkdown(ctx: SessionContext): string {
96	  const lines: string[] = [
97	    "## CorgiSpec Project Context",
98	    `- **Schema**: ${ctx.schema}`,
99	    `- **Isolation mode**: ${ctx.isolationMode}`,
100	  ];
101	
102	  if (ctx.activeChanges.length > 0) {
103	    lines.push("- **Active changes**:");
104	    for (const change of ctx.activeChanges) {
105	      const path = change.worktreePath ?? "no worktree";
106	      const status = change.currentGroup ?? "planning";
107	      lines.push(`  - ${change.name} \u2192 ${path} (${status})`);
108	    }
109	  } else {
110	    lines.push("- **Active changes**: (none)");
111	  }
112	
113	  lines.push(`- **Current branch**: ${ctx.currentBranch}`);
114	  lines.push(`- **Worktree path**: ${ctx.worktreePath}`);
115	  lines.push(
116	    "- **Hooks active**: SessionStart, PreToolUse, PostToolUse, Stop, PostCompact"
117	  );
118	
119	  return lines.join("\n");
