139	/**
140	 * Scan openspec/changes/ for active change directories.
141	 */
142	export function scanActiveChanges(
143	  cwd: string,
144	  config: OpenSpecConfig
145	): ActiveChange[] {
146	  const changesDir = resolve(cwd, "openspec/changes");
147	  if (!existsSync(changesDir)) return [];
148	
149	  const entries = readdirSync(changesDir, { withFileTypes: true });
150	  const changes: ActiveChange[] = [];
151	
152	  for (const entry of entries) {
153	    if (!entry.isDirectory()) continue;
154	
155	    const changeName = entry.name;
156	    const worktreePath = resolveChangeWorktree(cwd, config, changeName);
157	    const currentGroup = resolveCurrentGroup(cwd, changeName);
158	
159	    changes.push({
160	      name: changeName,
161	      worktreePath,
162	      currentGroup,
163	    });
164	  }
165	
166	  return changes;
167	}
