171	/**
172	 * Read JSON from stdin (for PreToolUse and Stop hooks).
173	 */
174	export async function readStdinJson(): Promise<HookInput> {
175	  return new Promise((resolve, reject) => {
176	    let data = "";
177	    process.stdin.setEncoding("utf-8");
178	    process.stdin.on("data", (chunk: string) => {
179	      data += chunk;
180	    });
181	    process.stdin.on("end", () => {
182	      try {
183	        if (!data.trim()) {
184	          resolve({});
185	          return;
186	        }
187	        resolve(JSON.parse(data) as HookInput);
188	      } catch {
189	        reject(new Error(`Failed to parse stdin JSON: ${data}`));
190	      }
191	    });
192	    process.stdin.on("error", reject);
193	  });
194	}
