238	  {
239	    pattern: /\brm\s+(-[a-zA-Z]*f[a-zA-Z]*\s+)?(-[a-zA-Z]*r[a-zA-Z]*\s+)?\/(\s|$)/,
240	    message: "Blocked: rm -rf / or equivalent destructive command detected.",
241	  },
242	  {
243	    pattern: /\bgit\s+push\s+.*--force\s+.*\bmain\b/,
244	    message:
245	      "Blocked: Force push to main branch detected. Use a feature branch instead.",
246	  },
247	  {
248	    // Short-form -f flag (not matched by --force pattern)
249	    pattern: /\bgit\s+push\s+(?!.*--force)(?=.*-f)\S.*\bmain\b/,
250	    message:
251	      "Blocked: Force push to main branch detected. Use a feature branch instead.",
252	  },
253	];
