323	// ─── Hook Configuration Detection ───────────────────────────────────────
324	
325	export interface HookConfigStatus {
326	  configured: boolean;
327	  platform: "claude" | "opencode" | "codex" | null;
328	  events: string[];
329	  configFile: string | null;
330	}
331	
332	/**
333	 * Detect whether hook configuration is present for any supported platform.
334	 * Checks Claude Code, OpenCode (deep), and Codex configs in priority order.
335	 */
336	export function detectHookConfig(cwd: string): HookConfigStatus {
337	  // 1. Claude Code / OpenCode bridge: .claude/settings.json with "hooks" key
338	  const claudeSettingsPath = resolve(cwd, ".claude/settings.json");
339	  if (existsSync(claudeSettingsPath)) {
340	    try {
341	      const data = JSON.parse(readFileSync(claudeSettingsPath, "utf-8"));
342	      if (data.hooks && typeof data.hooks === "object") {
343	        const events = Object.keys(data.hooks);
344	        return {
345	          configured: true,
346	          platform: "claude",
347	          events,
348	          configFile: claudeSettingsPath,
349	        };
350	      }
351	    } catch {
352	      // Invalid JSON — treat as not configured
353	    }
354	  }
355	
356	  // 2. OpenCode deep plugin: .opencode/plugins/corgispec-deep.ts
357	  const deepPluginPath = resolve(cwd, ".opencode/plugins/corgispec-deep.ts");
358	  if (existsSync(deepPluginPath)) {
359	    try {
360	      const content = readFileSync(deepPluginPath, "utf-8");
361	      if (content.includes("CorgiSpecDeep")) {
362	        return {
363	          configured: true,
364	          platform: "opencode",
365	          events: ["SessionStart", "PreToolUse", "PostToolUse", "Stop", "PostCompact"],
366	          configFile: deepPluginPath,
367	        };
368	      }
369	    } catch {
370	      // Unreadable — treat as not configured
371	    }
372	  }
373	
374	  // 3. Codex: .codex/config.toml with hooks entries
375	  const codexConfigPath = resolve(cwd, ".codex/config.toml");
376	  if (existsSync(codexConfigPath)) {
377	    try {
378	      const content = readFileSync(codexConfigPath, "utf-8");
379	      if (content.includes("hooks = true") || content.includes("[[hooks.")) {
380	        const events: string[] = [];
381	        const eventPattern = /\[\[hooks\.(\w+)\]\]/g;
382	        let match: RegExpExecArray | null;
383	        while ((match = eventPattern.exec(content)) !== null) {
384	          const event = match[1]!;
385	          if (!events.includes(event)) {
386	            events.push(event);
387	          }
388	        }
389	        return {
390	          configured: true,
391	          platform: "codex",
392	          events,
393	          configFile: codexConfigPath,
394	        };
395	      }
396	    } catch {
397	      // Unreadable — treat as not configured
398	    }
399	  }
400	
401	  return { configured: false, platform: null, events: [], configFile: null };
402	}
