404	// ─── Helpers ────────────────────────────────────────────────────────────
405	
406	function getCurrentBranch(): string {
407	  try {
408	    return execSync("git rev-parse --abbrev-ref HEAD", {
409	      encoding: "utf-8",
410	      stdio: ["pipe", "pipe", "pipe"],
411	    }).trim();
412	  } catch {
413	    return "(unknown)";
414	  }
415	}
416	
417	function resolveWorktreePath(
418	  cwd: string,
419	  config: OpenSpecConfig,
420	  branch: string
421	): string {
422	  if (!config.isolation || config.isolation.mode === "none") {
423	    return "N/A";
424	  }
425	  const root = config.isolation.root ?? ".worktrees";
426	  // Try to match branch to worktree
427	  const prefix = config.isolation.branch_prefix ?? "feat/";
428	  const changeName = branch.startsWith(prefix)
429	    ? branch.slice(prefix.length)
430	    : branch;
431	  const wtPath = resolve(cwd, root, changeName);
432	  if (existsSync(wtPath)) {
433	    return relative(cwd, wtPath) || wtPath;
434	  }
435	  return "N/A";
436	}
437	
438	function resolveChangeWorktree(
439	  cwd: string,
440	  config: OpenSpecConfig,
441	  changeName: string
442	): string | null {
443	  if (!config.isolation || config.isolation.mode === "none") {
444	    return null;
445	  }
446	  const root = config.isolation.root ?? ".worktrees";
447	  const wtPath = resolve(cwd, root, changeName);
448	  if (existsSync(wtPath)) {
449	    return relative(cwd, wtPath) || wtPath;
450	  }
451	  return null;
452	}
453	
454	function resolveCurrentGroup(cwd: string, changeName: string): string | null {
455	  const tasksPath = resolve(cwd, "openspec/changes", changeName, "tasks.md");
456	  if (!existsSync(tasksPath)) return null;
457	
458	  const content = readFileSync(tasksPath, "utf-8");
459	  const lines = content.split("\n");
460	
461	  let inGroup = false;
462	  let groupName = "";
463	  let groupNum = "";
464	
465	  for (const line of lines) {
466	    const headingMatch = line.match(/^## (\d+)\.\s+(.+)/);
467	    if (headingMatch) {
468	      groupNum = headingMatch[1]!;
469	      groupName = headingMatch[2]!.trim();
470	      inGroup = true;
471	      continue;
472	    }
473	
474	    if (inGroup) {
475	      const taskMatch = line.match(/^\s*- \[ \]\s+/);
476	      if (taskMatch) {
477	        return `Group ${groupNum} in-progress`;
478	      }
479	      // If we hit a new heading without finding unchecked tasks, this group is done
480	      if (line.match(/^## /)) {
481	        inGroup = false;
482	      }
483	    }
484	  }
485	
486	  // If all groups are done
487	  if (groupName) {
488	    return "all groups done";
489	  }
490	
491	  return null;
492	}
