9	const CONFIG_TEMPLATE = `schema: {{schema}}
10	
11	# Worktree isolation (optional)
12	# When enabled, each change gets its own git worktree + feature branch
13	# for parallel development. All propose/apply/review work happens
14	# inside the dedicated worktree. Archive cleans up the worktree
15	# but preserves the branch for merging via MR.
16	# Example:
17	#   isolation:
18	#     mode: worktree       # worktree | none (default: none)
19	#     root: .worktrees     # worktree root directory (default: .worktrees)
20	#     branch_prefix: feat/ # feature branch prefix (default: feat/)
21	
22	# Project context (optional)
23	# This is shown to AI when creating artifacts.
24	# Add your tech stack, conventions, style guides, domain knowledge, etc.
25	# Example:
26	#   context: |
27	#     Tech stack: TypeScript, React, Node.js
28	#     We use conventional commits
29	#     Domain: e-commerce platform
30	
31	# Per-artifact rules (optional)
32	# Add custom rules for specific artifacts.
33	# Example:
34	#   rules:
35	#     proposal:
36	#       - Keep proposals under 500 words
37	#       - Always include a "Non-goals" section
38	#     tasks:
39	#       - Break tasks into chunks of max 2 hours
40	`;
41	
42	const VALID_SCHEMAS = ["gitlab-tracked", "github-tracked"] as const;
43	const VALID_PLATFORMS = ["claude", "opencode", "codex", "all"] as const;
44	
45	type SchemaOption = (typeof VALID_SCHEMAS)[number];
46	type PlatformOption = (typeof VALID_PLATFORMS)[number];
47	
48	interface InitOptions {
49	  schema?: string;
50	  platform?: string;
51	  path: string;
52	}
53	
54	export interface InitializeOpenSpecOptions {
55	  target: string;
56	  schema: SchemaOption;
57	  bundledSchemasDir?: string | null;
58	}
59	
60	export function createInitCommand(): Command {
61	  const cmd = new Command("init");
62	
63	  cmd
64	    .description("Initialize Corgi directory structure in a project")
65	    .argument("[path]", "Target directory (default: current directory)")
66	    .option(
67	      "--schema <schema>",
68	      "Schema to use (github-tracked or gitlab-tracked)"
69	    )
70	    .option(
71	      "--platform <platform>",
72	      "Create platform skill directories (claude, opencode, codex, all)"
73	    )
74	    .action((targetPath: string | undefined, opts: InitOptions) => {
75	      const cwd = resolve(opts.path ?? ".");
76	      const target = targetPath ? resolve(cwd, targetPath) : cwd;
77	
78	      try {
79	        // Check if already initialized
80	        const configPath = resolve(target, "openspec/config.yaml");
81	        if (existsSync(configPath)) {
82	          console.log("Corgi already initialized");
83	          return;
84	        }
85	
86	        // Validate schema option
87	        const schema = (opts.schema ?? "github-tracked") as SchemaOption;
88	        if (!VALID_SCHEMAS.includes(schema)) {
89	          console.error(
90	            `Error: Invalid schema '${opts.schema}'. Supported: ${VALID_SCHEMAS.join(", ")}`
91	          );
92	          process.exit(1);
93	        }
94	
95	        initializeOpenSpec({
96	          target,
97	          schema,
98	          bundledSchemasDir: findBundledSchemas(),
99	        });
100	
101	        console.log(`Initialized Corgi in ${target}`);
102	        console.log(`  Schema: ${schema}`);
103	        console.log(`  Config: openspec/config.yaml`);
104	        console.log(`  Changes: openspec/changes/`);
105	        console.log(`  Schemas: openspec/schemas/`);
106	
107	        // Handle platform option
108	        if (opts.platform) {
109	          const platform = opts.platform as PlatformOption;
110	          if (!VALID_PLATFORMS.includes(platform)) {
111	            console.error(
112	              `\nWarning: Invalid platform '${opts.platform}'. Supported: ${VALID_PLATFORMS.join(", ")}`
113	            );
114	          } else {
115	            initPlatformDirs(target, platform);
116	          }
117	        }
118	
119	        console.log(
120	          `\nRun \`corgispec propose <name>\` to start your first change.`
121	        );
122	      } catch (err: unknown) {
123	        const msg = err instanceof Error ? err.message : String(err);
124	        console.error(`Error: ${msg}`);
125	        process.exit(1);
126	      }
127	    });
128	
129	  return cmd;
130	}
131	
132	function initPlatformDirs(target: string, platform: PlatformOption): void {
133	  const platforms: string[] =
134	    platform === "all"
135	      ? ["claude", "opencode", "codex"]
136	      : [platform];
137	
138	  for (const p of platforms) {
139	    let dir: string;
140	    switch (p) {
141	      case "claude":
142	        dir = resolve(target, ".claude/skills");
143	        break;
144	      case "opencode":
145	        dir = resolve(target, ".opencode/skills");
146	        break;
147	      case "codex":
148	        dir = resolve(target, ".codex/skills");
149	        break;
150	      default:
151	        continue;
152	    }
153	
154	    if (!existsSync(dir)) {
155	      mkdirSync(dir, { recursive: true });
156	      console.log(`  Created: ${dir}`);
157	    } else {
158	      console.log(`  Exists: ${dir}`);
159	    }
160	  }
161	}
162	
163	export function initializeOpenSpec(options: InitializeOpenSpecOptions): void {
164	  const openspecDir = resolve(options.target, "openspec");
165	  const configPath = resolve(openspecDir, "config.yaml");
166	
167	  mkdirSync(resolve(openspecDir, "changes"), { recursive: true });
168	  mkdirSync(resolve(openspecDir, "schemas"), { recursive: true });
169	  mkdirSync(resolve(openspecDir, "specs"), { recursive: true });
170	
171	  const configContent = CONFIG_TEMPLATE.replace("{{schema}}", options.schema);
172	  writeFileSync(configPath, configContent);
173	
174	  if (!options.bundledSchemasDir) {
175	    return;
176	  }
177	
178	  const sourceSchema = resolve(options.bundledSchemasDir, options.schema);
179	  const targetSchema = resolve(openspecDir, "schemas", options.schema);
180	  if (existsSync(sourceSchema) && !existsSync(targetSchema)) {
181	    cpSync(sourceSchema, targetSchema, { recursive: true });
182	  }
183	}
184	
185	/**
186	 * Find bundled schemas relative to the CLI's install location.
187	 */
188	export function findBundledSchemas(): string | null {
189	  // When installed globally: dist/../assets/schemas
190	  // When running from source: look up from dist to assets
191	  const candidates = [
192	    resolve(__dirname, "../assets/schemas"),
193	    resolve(__dirname, "../../assets/schemas"),
194	    resolve(__dirname, "../../../openspec/schemas"),
195	  ];
196	
197	  for (const candidate of candidates) {
198	    if (existsSync(candidate)) {
199	      return candidate;
200	    }
201	  }
202	  return null;
203	}
