9	/**
10	 * Get the bundled skills directory from the package assets.
11	 */
12	export function getBundledSkillsDir(): string {
13	  // From dist/commands/ → ../assets/skills
14	  const fromDist = resolve(__dirname, "../assets/skills");
15	  if (existsSync(fromDist)) {
16	    return fromDist;
17	  }
18	  // Fallback for dev
19	  const fromSrc = resolve(__dirname, "../../assets/skills");
20	  if (existsSync(fromSrc)) {
21	    return fromSrc;
22	  }
23	  throw new Error(
24	    "Bundled skills not found. Run 'node scripts/bundle-assets.js' first."
25	  );
