82	export function createInstallCommand(): Command {
83	  const cmd = new Command("install");
84	
85	  cmd
86	    .description("Install bundled skills to user-level platform directories")
87	    .option(
88	      "--platform <platform>",
89	      "Install to specific platform only (claude, opencode, codex)"
90	    )
91	    .option("--dry-run", "Print planned operations without copying files")
92	    .action((opts) => {
93	      const dryRun = opts.dryRun ?? false;
94	      const platformFilter: Platform | undefined = opts.platform;
95	
96	      if (
97	        platformFilter &&
98	        !["claude", "opencode", "codex"].includes(platformFilter)
99	      ) {
100	        console.error(
101	          `Error: Invalid platform '${platformFilter}'. Choose: claude, opencode, codex`
102	        );
103	        process.exit(1);
104	      }
105	
106	      let sourceDir: string;
107	      try {
108	        sourceDir = getBundledSkillsDir();
109	      } catch (err) {
110	        console.error(
111	          err instanceof Error ? err.message : "Failed to locate bundled skills"
112	        );
113	        process.exit(1);
114	      }
115	
116	      const platforms: Platform[] = platformFilter
117	        ? [platformFilter]
118	        : ["claude", "opencode", "codex"];
119	
120	      if (dryRun) {
121	        console.log("DRY RUN — no files will be written\n");
