1	import { Command } from "commander";
2	import { resolve } from "node:path";
3	import { existsSync, accessSync, constants, readdirSync, readFileSync } from "node:fs";
4	import { homedir } from "node:os";
5	import { findConfigPath, loadConfig } from "../lib/config.js";
6	import { detectPlatforms } from "../lib/platform.js";
7	import { detectHookConfig } from "../lib/hooks.js";
8	import yaml from "js-yaml";
9	
10	interface CheckResult {
11	  name: string;
12	  passed: boolean;
13	  message: string;
14	  suggestion?: string;
15	}
16	
17	export function createDoctorCommand(): Command {
18	  const cmd = new Command("doctor");
19	
20	  cmd
21	    .description(
22	      "Diagnose runtime environment and report issues with suggestions"
23	    )
24	    .option("--path <dir>", "Working directory", ".")
25	    .option("--json", "Output as JSON")
26	    .action((opts) => {
27	      const cwd = resolve(opts.path);
28	      const results: CheckResult[] = [];
29	
30	      // 1. Node version check
31	      results.push(checkNodeVersion());
32	
33	      // 2. Skill directory checks
34	      results.push(...checkSkillDirs());
35	
36	      // 3. Config validation
37	      results.push(checkConfig(cwd));
38	
39	      // 4. Platform detection
40	      results.push(...checkPlatforms());
41	
42	      // 5. Hook configuration
43	      results.push(checkHooks(cwd));
44	
45	      // 6. Schema validation
46	      results.push(checkSchemas(cwd));
47	
48	      // Output
49	      if (opts.json) {
50	        console.log(JSON.stringify(results, null, 2));
51	      } else {
52	        printResults(results);
53	      }
54	
55	      // Exit code
56	      const hasFailure = results.some((r) => !r.passed);
57	      if (hasFailure) {
58	        process.exitCode = 1;
59	      }
60	    });
61	
62	  return cmd;
63	}
64	
65	function checkNodeVersion(): CheckResult {
66	  const version = process.versions.node;
67	  const major = parseInt(version.split(".")[0]!, 10);
68	
69	  if (major >= 18) {
70	    return {
71	      name: "Node.js",
72	      passed: true,
73	      message: `v${version}`,
74	    };
75	  }
76	
77	  return {
78	    name: "Node.js",
79	    passed: false,
80	    message: `v${version} (requires >= 18)`,
81	    suggestion: "Upgrade Node.js to version 18 or later.",
82	  };
83	}
84	
85	function checkSkillDirs(): CheckResult[] {
86	  const results: CheckResult[] = [];
87	  const home = homedir();
88	
89	  const dirs = [
90	    { name: "~/.claude/skills/", path: resolve(home, ".claude/skills") },
91	    {
92	      name: "~/.config/opencode/skill/",
93	      path: resolve(home, ".config/opencode/skill"),
94	    },
95	  ];
96	
97	  for (const dir of dirs) {
98	    if (!existsSync(dir.path)) {
99	      results.push({
100	        name: dir.name,
101	        passed: false,
102	        message: "not found",
103	        suggestion: `Run \`corgispec install\` to create.`,
104	      });
105	    } else {
106	      // Check writable
107	      try {
108	        accessSync(dir.path, constants.W_OK);
109	        results.push({
110	          name: dir.name,
111	          passed: true,
112	          message: "exists and writable",
113	        });
114	      } catch {
115	        results.push({
116	          name: dir.name,
117	          passed: false,
118	          message: "exists but not writable",
119	          suggestion: `Check permissions on ${dir.path}`,
120	        });
121	      }
122	    }
123	  }
124	
125	  return results;
126	}
127	
128	function checkConfig(cwd: string): CheckResult {
129	  const configPath = findConfigPath(cwd);
130	
131	  if (!configPath) {
132	    return {
133	      name: "Config",
134	      passed: true, // Not a failure — just not in a project
135	      message: "not found (not in a Corgi project)",
136	    };
137	  }
138	
139	  try {
140	    const config = loadConfig(configPath);
141	    return {
142	      name: "Config",
143	      passed: true,
144	      message: `valid (schema: ${config.schema})`,
145	    };
146	  } catch (err: unknown) {
147	    const msg = err instanceof Error ? err.message : String(err);
148	    return {
149	      name: "Config",
150	      passed: false,
151	      message: msg,
152	      suggestion: "Fix the config.yaml file or run `corgispec init` to recreate it.",
153	    };
154	  }
155	}
156	
157	function checkPlatforms(): CheckResult[] {
158	  const results: CheckResult[] = [];
159	  const platforms = detectPlatforms();
160	  const detected = platforms.filter((p) => p.detected);
161	
162	  if (detected.length === 0) {
163	    results.push({
164	      name: "AI Platforms",
165	      passed: true, // Not a hard failure
166	      message:
167	        "No AI platforms detected. Run `corgispec install` after setting up your platform.",
168	    });
169	  } else {
170	    for (const p of detected) {
171	      results.push({
172	        name: `${p.platform} (platform)`,
173	        passed: true,
174	        message: "detected",
175	      });
176	    }
177	  }
178	
179	  return results;
180	}
181	
182	function checkSchemas(cwd: string): CheckResult {
183	  // Check project schemas first, then bundled schemas
184	  const schemaDirs = [
185	    resolve(cwd, "openspec/schemas"),
186	    resolve(import.meta.dirname ?? ".", "../assets/schemas"),
187	    resolve(import.meta.dirname ?? ".", "../../assets/schemas"),
188	  ];
189	
190	  let schemasDir: string | null = null;
191	  for (const dir of schemaDirs) {
192	    if (existsSync(dir)) {
193	      schemasDir = dir;
194	      break;
195	    }
196	  }
197	
198	  if (!schemasDir) {
199	    return {
200	      name: "Schemas",
201	      passed: true, // Not a hard failure if no schemas available
202	      message: "no schemas directory found",
203	    };
204	  }
205	
206	  try {
207	    const entries = readdirSync(schemasDir, { withFileTypes: true });
208	    const schemaDirNames = entries
209	      .filter((e) => e.isDirectory())
210	      .map((e) => e.name);
211	
212	    let validCount = 0;
213	    const errors: string[] = [];
214	
215	    for (const name of schemaDirNames) {
216	      const schemaFile = resolve(schemasDir, name, "schema.yaml");
217	      if (!existsSync(schemaFile)) {
218	        errors.push(`${name}/schema.yaml missing`);
219	        continue;
220	      }
221	
222	      try {
223	        const content = readFileSync(schemaFile, "utf-8");
224	        const parsed = yaml.load(content) as Record<string, unknown> | null;
225	
226	        // Validate required schema structure
227	        if (!parsed || typeof parsed !== "object") {
228	          errors.push(`${name}/schema.yaml is not a valid YAML document`);
229	          continue;
230	        }
231	
232	        if (!parsed.name || typeof parsed.name !== "string") {
233	          errors.push(`${name}/schema.yaml missing required 'name' field`);
234	          continue;
235	        }
236	
237	        if (!parsed.artifacts || !Array.isArray(parsed.artifacts)) {
238	          errors.push(`${name}/schema.yaml missing required 'artifacts' array`);
239	          continue;
240	        }
241	
242	        validCount++;
243	      } catch (parseErr: unknown) {
244	        const msg = parseErr instanceof Error ? parseErr.message : String(parseErr);
245	        errors.push(`${name}/schema.yaml is not valid YAML: ${msg}`);
246	      }
247	    }
248	
249	    if (errors.length > 0) {
250	      return {
251	        name: "Schemas",
252	        passed: false,
253	        message: errors.join("; "),
254	        suggestion: "Reinstall or repair schema files.",
255	      };
256	    }
257	
258	    return {
259	      name: "Schemas",
260	      passed: true,
261	      message: `${validCount} schema(s) valid`,
262	    };
263	  } catch (err: unknown) {
264	    const msg = err instanceof Error ? err.message : String(err);
265	    return {
266	      name: "Schemas",
267	      passed: false,
268	      message: msg,
269	      suggestion: "Check schema directory permissions.",
270	    };
271	  }
272	}
273	
274	function checkHooks(cwd: string): CheckResult {
275	  const hookStatus = detectHookConfig(cwd);
276	
277	  if (hookStatus.configured) {
278	    return {
279	      name: "Hooks",
280	      passed: true,
281	      message: `configured for ${hookStatus.platform} (${hookStatus.events.join(", ")})`,
282	    };
283	  }
284	
285	  return {
286	    name: "Hooks",
287	    passed: true,
288	    message: "not configured",
289	    suggestion: "Run `corgispec hooks generate --platform <name>` to enable hooks.",
290	  };
291	}
292	
293	function printResults(results: CheckResult[]): void {
294	  console.log("corgispec doctor\n");
295	
296	  let passCount = 0;
297	  let failCount = 0;
298	
299	  for (const r of results) {
300	    const icon = r.passed ? "✓" : "✗";
301	    const status = r.passed ? "pass" : "FAIL";
302	    console.log(`  ${icon} ${r.name}: ${r.message} (${status})`);
303	    if (!r.passed && r.suggestion) {
304	      console.log(`    → ${r.suggestion}`);
305	    }
306	    if (r.passed) passCount++;
307	    else failCount++;
308	  }
309	
310	  console.log();
311	  if (failCount === 0) {
312	    console.log(`All ${passCount} checks passed.`);
313	  } else {
314	    console.log(
315	      `${passCount} passed, ${failCount} failed.`
316	    );
317	  }
318	}
