56	/**
57	 * Generate a Graphviz DOT graph from skill dependencies.
58	 */
59	function toDot(skills: DiscoveredSkill[]): string {
60	  const lines: string[] = ["digraph skills {"];
61	  lines.push("  rankdir=BT;");
62	  lines.push("  node [shape=box, style=filled];");
63	  lines.push("");
64	
65	  // Tier-based colors
66	  const tierColors: Record<string, string> = {
67	    atom: "#e8f5e9",
68	    molecule: "#e3f2fd",
69	    compound: "#fce4ec",
70	  };
71	
72	  // Add nodes
73	  for (const skill of skills) {
74	    const color = tierColors[skill.meta.tier] || "#ffffff";
75	    lines.push(
76	      `  "${skill.slug}" [label="${skill.slug}\\n(${skill.meta.tier})", fillcolor="${color}"];`
77	    );
78	  }
79	
80	  lines.push("");
81	
82	  // Add edges
83	  for (const skill of skills) {
84	    for (const dep of skill.meta.depends_on) {
85	      if (skills.some((s) => s.slug === dep)) {
86	        lines.push(`  "${dep}" -> "${skill.slug}";`);
87	      }
88	    }
89	  }
90	
91	  lines.push("}");
92	  return lines.join("\n");
93	}
