170	// ─── Task Group Parsing ─────────────────────────────────────────────────
171	
172	/**
173	 * Parse task groups from tasks.md content.
174	 */
175	export function parseTaskGroups(content: string): TaskGroup[] {
176	  const groups: TaskGroup[] = [];
177	  const lines = content.split("\n");
178	  let currentGroup: TaskGroup | null = null;
179	
180	  for (const line of lines) {
181	    // Match ## N. Group Name
182	    const headingMatch = line.match(/^## (\d+)\.\s+(.+)/);
183	    if (headingMatch) {
184	      if (currentGroup) {
185	        finalizeGroup(currentGroup);
186	        groups.push(currentGroup);
187	      }
188	      currentGroup = {
189	        number: parseInt(headingMatch[1]!, 10),
190	        name: headingMatch[2]!.trim(),
191	        tasks: [],
192	        totalTasks: 0,
193	        completedTasks: 0,
194	        status: "pending",
195	      };
196	      continue;
197	    }
198	
199	    // Match task items: - [ ] or - [x]
200	    if (currentGroup) {
201	      const taskMatch = line.match(/^\s*- \[([ x])\]\s+([\d.]+)\s+(.*)/);
202	      if (taskMatch) {
203	        const done = taskMatch[1] === "x";
204	        currentGroup.tasks.push({
205	          id: taskMatch[2]!,
206	          description: taskMatch[3]!.trim(),
207	          done,
208	        });
209	      }
210	    }
211	  }
212	
213	  if (currentGroup) {
214	    finalizeGroup(currentGroup);
215	    groups.push(currentGroup);
216	  }
217	
218	  return groups;
219	}
220	
221	function finalizeGroup(group: TaskGroup): void {
222	  group.totalTasks = group.tasks.length;
223	  group.completedTasks = group.tasks.filter((t) => t.done).length;
224	
225	  if (group.completedTasks === group.totalTasks && group.totalTasks > 0) {
226	    group.status = "done";
227	  } else if (group.completedTasks > 0) {
228	    group.status = "in_progress";
229	  } else {
230	    group.status = "pending";
231	  }
232	}
