198	/**
199	 * Check if a file_path is a valid write target given the current isolation config.
200	 * Returns null if allowed, or a rejection message if blocked.
201	 */
202	export function validateWriteTarget(
203	  filePath: string,
204	  cwd: string,
205	  config: OpenSpecConfig
206	): string | null {
207	  const isolation = config.isolation;
208	
209	  // No isolation = all writes allowed
210	  if (!isolation || isolation.mode === "none") {
211	    return null;
212	  }
213	
214	  // Worktree isolation: writes must be inside the active worktree
215	  if (isolation.mode === "worktree") {
216	    const root = isolation.root ?? ".worktrees";
217	    const absPath = resolve(cwd, filePath);
218	    const worktreeRoot = resolve(cwd, root);
219	
220	    // Allow writes inside any worktree
221	    if (absPath.startsWith(worktreeRoot + "/") || absPath.startsWith(worktreeRoot + "\\")) {
222	      return null;
223	    }
224	
225	    // Block writes outside worktrees
226	    return (
227	      `Blocked: Write to "${filePath}" is outside the worktree root "${root}". ` +
228	      "When isolation.mode is worktree, all writes must go to a worktree directory."
229	    );
230	  }
231	
232	  return null;
233	}
