255	/**
256	 * Check if a bash command contains dangerous patterns.
257	 * Returns null if safe, or a rejection message if dangerous.
258	 */
259	export function checkDangerousCommand(command: string): string | null {
260	  for (const { pattern, message } of DANGEROUS_PATTERNS) {
261	    if (pattern.test(command)) {
262	      return message;
263	    }
264	  }
265	  return null;
266	}
