268	// ─── Task Group Postcondition Check ─────────────────────────────────────
269	
270	/**
271	 * Check postconditions for the current task group of a change.
272	 * Returns null if all pass, or a list of failure messages.
273	 */
274	export function checkTaskGroupPostconditions(
275	  cwd: string,
276	  changeName: string
277	): string[] | null {
278	  const tasksPath = resolve(cwd, "openspec/changes", changeName, "tasks.md");
279	  if (!existsSync(tasksPath)) return null;
280	
281	  const content = readFileSync(tasksPath, "utf-8");
282	  const lines = content.split("\n");
283	
284	  // Find the first group with incomplete tasks
285	  let inCurrentGroup = false;
286	  let currentGroupName = "";
287	  const incompleteTasks: string[] = [];
288	
289	  for (const line of lines) {
290	    const headingMatch = line.match(/^## (\d+)\.\s+(.+)/);
291	    if (headingMatch) {
292	      // If we were in a group and found a new heading, stop
293	      if (inCurrentGroup && incompleteTasks.length === 0) {
294	        break;
295	      }
296	      if (inCurrentGroup) {
297	        break;
298	      }
299	      currentGroupName = headingMatch[2]!.trim();
300	      inCurrentGroup = true;
301	      incompleteTasks.length = 0;
302	      continue;
303	    }
304	
305	    if (inCurrentGroup) {
306	      const taskMatch = line.match(/^\s*- \[ \]\s+(.*)/);
307	      if (taskMatch) {
308	        incompleteTasks.push(taskMatch[1]!.trim());
309	      }
310	    }
311	  }
312	
313	  if (incompleteTasks.length > 0) {
314	    return [
315	      `Incomplete tasks in "${currentGroupName}":`,
316	      ...incompleteTasks.map((t) => `  - ${t}`),
317	    ];
318	  }
319	
320	  return null;
321	}
