44	function listDirEntries(root: string): string[] {
45	  const entries: string[] = [];
46	  if (!existsSync(root)) {
47	    return entries;
48	  }
49	
50	  const walk = (dir: string, prefix = "") => {
51	    for (const entry of readdirSync(dir)) {
52	      const fullPath = resolve(dir, entry);
53	      const relativePath = prefix ? `${prefix}/${entry}` : entry;
54	      if (statSync(fullPath).isDirectory()) {
55	        walk(fullPath, relativePath);
56	      } else {
57	        entries.push(relativePath);
58	      }
59	    }
60	  };
61	
62	  walk(root);
63	  return entries;
64	}
