157	/**
158	 * Generate instruction JSON for the review phase.
159	 */
160	export function resolveReviewInstruction(
161	  cwd: string,
162	  changeName: string
163	): ReviewInstruction {
164	  const changeInfo = getChangeInfo(cwd, changeName);
165	  const changeDir = resolve(cwd, "openspec/changes", changeName);
166	
167	  const completedGroups = changeInfo.taskGroups.filter(
168	    (g) => g.status === "done"
169	  );
170	
171	  // Context files: all artifacts
172	  const contextFiles: string[] = [];
173	  const proposalPath = resolve(changeDir, "proposal.md");
174	  if (existsSync(proposalPath)) contextFiles.push(proposalPath);
175	  const designPath = resolve(changeDir, "design.md");
176	  if (existsSync(designPath)) contextFiles.push(designPath);
177	  const tasksPath = resolve(changeDir, "tasks.md");
178	  if (existsSync(tasksPath)) contextFiles.push(tasksPath);
179	  const specsDir = resolve(changeDir, "specs");
180	  if (existsSync(specsDir)) addMarkdownFilesFromDir(specsDir, contextFiles);
181	
182	  // List of artifact IDs that exist
183	  const artifacts = changeInfo.artifacts
184	    .filter((a) => a.exists)
185	    .map((a) => a.id);
186	
187	  const instruction = `Review the completed task groups against the specifications and design.
188	
189	Check:
190	1. All spec scenarios are implemented and testable
191	2. Design decisions were followed
192	3. No tasks were skipped or partially implemented
193	4. Code quality meets project standards
194	
195	Completed groups: ${completedGroups.map((g) => `${g.number}. ${g.name}`).join(", ")}
196	Total progress: ${changeInfo.completedTasks}/${changeInfo.totalTasks} tasks`;
197	
198	  return {
199	    changeName,
200	    state: changeInfo.state,
201	    completedGroups,
202	    artifacts,
203	    instruction,
204	    contextFiles,
205	  };
