126	      for (const platform of platforms) {
127	        const targetDir = getSkillDir(platform);
128	        console.log(`\n${platform}: ${targetDir}`);
129	
130	        const installed = installSkillsTo(sourceDir, targetDir, dryRun);
131	        totalInstalled += installed.length;
132	
133	        if (installed.length === 0) {
134	          console.log("  (no skills to install)");
135	        }
136	      }
137	
138	      console.log(
139	        `\n${dryRun ? "Would install" : "Installed"} ${totalInstalled} skill(s) across ${platforms.length} platform(s).`
140	      );
141	
142	      if (!dryRun && totalInstalled > 0) {
143	        console.log(
144	          "\n💡 Tip: Run `corgispec hooks generate` to enable auto context injection & security guards."
145	        );
146	      }
147	    });
148	
149	  return cmd;
150	}
