9	const CONFIG_TEMPLATE = `schema: {{schema}}
10	
11	# Worktree isolation (optional)
12	# When enabled, each change gets its own git worktree + feature branch
13	# for parallel development. All propose/apply/review work happens
14	# inside the dedicated worktree. Archive cleans up the worktree
15	# but preserves the branch for merging via MR.
16	# Example:
17	#   isolation:
18	#     mode: worktree       # worktree | none (default: none)
19	#     root: .worktrees     # worktree root directory (default: .worktrees)
20	#     branch_prefix: feat/ # feature branch prefix (default: feat/)
