28	#     We use conventional commits
29	#     Domain: e-commerce platform
30	
31	# Per-artifact rules (optional)
32	# Add custom rules for specific artifacts.
33	# Example:
34	#   rules:
35	#     proposal:
36	#       - Keep proposals under 500 words
37	#       - Always include a "Non-goals" section
38	#     tasks:
39	#       - Break tasks into chunks of max 2 hours
40	`;
