42	const VALID_SCHEMAS = ["gitlab-tracked", "github-tracked"] as const;
43	const VALID_PLATFORMS = ["claude", "opencode", "codex", "all"] as const;
44	
45	type SchemaOption = (typeof VALID_SCHEMAS)[number];
46	type PlatformOption = (typeof VALID_PLATFORMS)[number];
