60	export function createInitCommand(): Command {
61	  const cmd = new Command("init");
62	
63	  cmd
64	    .description("Initialize Corgi directory structure in a project")
65	    .argument("[path]", "Target directory (default: current directory)")
66	    .option(
67	      "--schema <schema>",
68	      "Schema to use (github-tracked or gitlab-tracked)"
69	    )
70	    .option(
71	      "--platform <platform>",
72	      "Create platform skill directories (claude, opencode, codex, all)"
73	    )
74	    .action((targetPath: string | undefined, opts: InitOptions) => {
75	      const cwd = resolve(opts.path ?? ".");
76	      const target = targetPath ? resolve(cwd, targetPath) : cwd;
77	
78	      try {
79	        // Check if already initialized
80	        const configPath = resolve(target, "openspec/config.yaml");
81	        if (existsSync(configPath)) {
82	          console.log("Corgi already initialized");
83	          return;
84	        }
85	
86	        // Validate schema option
87	        const schema = (opts.schema ?? "github-tracked") as SchemaOption;
88	        if (!VALID_SCHEMAS.includes(schema)) {
89	          console.error(
90	            `Error: Invalid schema '${opts.schema}'. Supported: ${VALID_SCHEMAS.join(", ")}`
91	          );
92	          process.exit(1);
93	        }
94	
95	        initializeOpenSpec({
96	          target,
97	          schema,
98	          bundledSchemasDir: findBundledSchemas(),
99	        });
100	
101	        console.log(`Initialized Corgi in ${target}`);
102	        console.log(`  Schema: ${schema}`);
103	        console.log(`  Config: openspec/config.yaml`);
104	        console.log(`  Changes: openspec/changes/`);
105	        console.log(`  Schemas: openspec/schemas/`);
106	
107	        // Handle platform option
108	        if (opts.platform) {
109	          const platform = opts.platform as PlatformOption;
110	          if (!VALID_PLATFORMS.includes(platform)) {
111	            console.error(
112	              `\nWarning: Invalid platform '${opts.platform}'. Supported: ${VALID_PLATFORMS.join(", ")}`
113	            );
114	          } else {
115	            initPlatformDirs(target, platform);
116	          }
117	        }
118	
119	        console.log(
120	          `\nRun \`corgispec propose <name>\` to start your first change.`
121	        );
122	      } catch (err: unknown) {
123	        const msg = err instanceof Error ? err.message : String(err);
124	        console.error(`Error: ${msg}`);
125	        process.exit(1);
126	      }
127	    });
128	
129	  return cmd;
130	}
