163	export function initializeOpenSpec(options: InitializeOpenSpecOptions): void {
164	  const openspecDir = resolve(options.target, "openspec");
165	  const configPath = resolve(openspecDir, "config.yaml");
166	
167	  mkdirSync(resolve(openspecDir, "changes"), { recursive: true });
168	  mkdirSync(resolve(openspecDir, "schemas"), { recursive: true });
169	  mkdirSync(resolve(openspecDir, "specs"), { recursive: true });
170	
171	  const configContent = CONFIG_TEMPLATE.replace("{{schema}}", options.schema);
172	  writeFileSync(configPath, configContent);
173	
174	  if (!options.bundledSchemasDir) {
175	    return;
176	  }
177	
178	  const sourceSchema = resolve(options.bundledSchemasDir, options.schema);
179	  const targetSchema = resolve(openspecDir, "schemas", options.schema);
180	  if (existsSync(sourceSchema) && !existsSync(targetSchema)) {
181	    cpSync(sourceSchema, targetSchema, { recursive: true });
182	  }
183	}
184	
185	/**
186	 * Find bundled schemas relative to the CLI's install location.
187	 */
188	export function findBundledSchemas(): string | null {
189	  // When installed globally: dist/../assets/schemas
190	  // When running from source: look up from dist to assets
191	  const candidates = [
192	    resolve(__dirname, "../assets/schemas"),
193	    resolve(__dirname, "../../assets/schemas"),
194	    resolve(__dirname, "../../../openspec/schemas"),
195	  ];
196	
197	  for (const candidate of candidates) {
198	    if (existsSync(candidate)) {
199	      return candidate;
200	    }
201	  }
202	  return null;
203	}
