3	/**
4	 * bundle-assets.js
5	 *
6	 * Copies skill files, command assets, memory-init templates, JSON schemas,
7	 * and workflow schemas from the repo
8	 * source-of-truth locations into the package's assets/ directory for distribution.
9	 *
10	 * Run as part of prepublishOnly: npm run build && node scripts/bundle-assets.js
11	 *
12	 * Asset sources:
13	 *   .opencode/skills/<tier>/corgispec-*  → assets/skills/<tier>/
14	 *   .opencode/commands/*.md      → assets/commands/opencode/
15	 *   .claude/commands/corgi/*.md   → assets/commands/claude/corgi/
16	 *   .opencode/skills/corgispec-memory-init/templates/** → assets/memory-init/templates/
17	 *   schemas/                     → assets/schemas/ (JSON Schema files for validation)
18	 *   openspec/schemas/            → assets/schemas/ (workflow schemas for init/doctor)
19	 */
