21	import { cpSync, mkdirSync, rmSync, existsSync, readdirSync, readFileSync } from "node:fs";
22	import { resolve, dirname } from "node:path";
23	import { fileURLToPath } from "node:url";
24	import { createHash } from "node:crypto";
25	
26	const __dirname = dirname(fileURLToPath(import.meta.url));
27	const packageRoot = resolve(__dirname, "..");
28	const repoRoot = resolve(packageRoot, "../..");
29	
30	const assetsDir = process.env.CORGISPEC_ASSETS_DIR
31	  ? resolve(process.env.CORGISPEC_ASSETS_DIR)
32	  : resolve(packageRoot, "assets");
33	
34	// --- Clean and recreate assets directory ---
35	if (existsSync(assetsDir)) {
36	  rmSync(assetsDir, { recursive: true });
37	}
38	mkdirSync(assetsDir, { recursive: true });
39	
40	let totalFiles = 0;
41	const errors = [];
42	
43	function copyMarkdownFiles(sourceDir, destDir) {
44	  mkdirSync(destDir, { recursive: true });
45	
46	  if (!existsSync(sourceDir)) {
47	    return 0;
48	  }
49	
50	  const files = readdirSync(sourceDir).filter((file) => file.endsWith(".md"));
51	  for (const file of files) {
52	    cpSync(resolve(sourceDir, file), resolve(destDir, file));
53	  }
54	
55	  return files.length;
56	}
