1	import Ajv2020, { type ValidateFunction, type ErrorObject } from "ajv/dist/2020.js";
2	import { readFileSync, existsSync, readdirSync } from "node:fs";
3	import { resolve, dirname } from "node:path";
4	import { fileURLToPath } from "node:url";
5	
6	const __dirname = dirname(fileURLToPath(import.meta.url));
7	
8	/**
9	 * Get the path to the bundled assets directory.
10	 * In the built package: dist/ → ../assets/
11	 * In dev (src/lib/): ../../assets/
12	 */
13	function getAssetsDir(): string {
14	  // Try relative to dist/ first (production)
15	  const fromDist = resolve(__dirname, "../assets");
16	  if (existsSync(fromDist)) {
17	    return fromDist;
18	  }
19	  // Fallback for dev (when running from src/lib/)
20	  const fromSrc = resolve(__dirname, "../../assets");
21	  if (existsSync(fromSrc)) {
22	    return fromSrc;
23	  }
24	  throw new SchemaError("Assets directory not found. Run 'npm run build' or 'node scripts/bundle-assets.js'.");
25	}
26	
27	export class SchemaError extends Error {
28	  constructor(message: string) {
29	    super(message);
30	    this.name = "SchemaError";
31	  }
32	}
33	
34	/**
35	 * Result of a schema validation.
36	 */
37	export interface ValidationResult {
38	  valid: boolean;
39	  errors?: ErrorObject[];
40	}
41	
42	/**
43	 * Manages JSON Schema loading and validation.
44	 */
45	export class SchemaRegistry {
46	  private ajv: InstanceType<typeof Ajv2020>;
47	  private validators: Map<string, ValidateFunction> = new Map();
48	  private schemasDir: string;
49	
50	  constructor(schemasDir?: string) {
51	    this.schemasDir = schemasDir ?? resolve(getAssetsDir(), "schemas");
52	    this.ajv = new Ajv2020({ allErrors: true, strict: false });
53	  }
54	
55	  /**
56	   * List all available schema files.
57	   */
58	  listSchemas(): string[] {
59	    if (!existsSync(this.schemasDir)) {
60	      return [];
61	    }
62	    return readdirSync(this.schemasDir).filter((f) => f.endsWith(".json"));
63	  }
64	
65	  /**
66	   * Load a schema by filename and compile it for validation.
67	   */
68	  loadSchema(filename: string): ValidateFunction {
69	    if (this.validators.has(filename)) {
70	      return this.validators.get(filename)!;
71	    }
72	
73	    const schemaPath = resolve(this.schemasDir, filename);
74	    if (!existsSync(schemaPath)) {
75	      throw new SchemaError(`Schema file not found: ${schemaPath}`);
76	    }
77	
78	    let schemaJson: unknown;
79	    try {
80	      const content = readFileSync(schemaPath, "utf-8");
81	      schemaJson = JSON.parse(content);
82	    } catch (err) {
83	      throw new SchemaError(
84	        `Failed to parse schema '${filename}': ${err instanceof Error ? err.message : String(err)}`
85	      );
86	    }
87	
88	    let validator: ValidateFunction;
89	    try {
90	      validator = this.ajv.compile(schemaJson as object);
91	    } catch (err) {
92	      throw new SchemaError(
93	        `Failed to compile schema '${filename}': ${err instanceof Error ? err.message : String(err)}`
94	      );
95	    }
96	
97	    this.validators.set(filename, validator);
98	    return validator;
99	  }
100	
101	  /**
102	   * Validate data against a named schema.
103	   */
104	  validate(schemaFilename: string, data: unknown): ValidationResult {
105	    const validator = this.loadSchema(schemaFilename);
106	    const valid = validator(data) as boolean;
107	    return {
108	      valid,
109	      errors: valid ? undefined : (validator.errors ?? undefined),
110	    };
111	  }
112	
113	  /**
114	   * Check if all bundled schemas are valid JSON Schema documents.
115	   * Returns an array of { filename, error } for any that fail.
116	   */
117	  validateAllSchemas(): Array<{ filename: string; error?: string }> {
118	    const results: Array<{ filename: string; error?: string }> = [];
119	    const schemas = this.listSchemas();
120	
121	    for (const filename of schemas) {
122	      try {
123	        this.loadSchema(filename);
124	        results.push({ filename });
125	      } catch (err) {
126	        results.push({
127	          filename,
128	          error: err instanceof Error ? err.message : String(err),
129	        });
130	      }
131	    }
132	
133	    return results;
134	  }
135	}
136	
137	/**
138	 * Create a schema registry using the bundled assets.
139	 */
140	export function createSchemaRegistry(schemasDir?: string): SchemaRegistry {
141	  return new SchemaRegistry(schemasDir);
142	}
