3	/**
4	 * Check that the running Node.js version meets the minimum requirement.
5	 * Exits the process with code 1 if the version is too low.
6	 */
7	export function checkNodeVersion(): void {
8	  const current = process.versions.node;
9	  const major = parseInt(current.split(".")[0]!, 10);
10	
11	  if (major < MIN_NODE_MAJOR) {
12	    process.stderr.write(
13	      `Error: Node.js >= ${MIN_NODE_MAJOR} required (current: v${current})\n`
14	    );
