5	/**
6	 * Supported AI coding platforms.
7	 */
8	export type Platform = "claude" | "opencode" | "codex";
9	
10	/**
11	 * Platform detection result.
12	 */
13	export interface PlatformInfo {
14	  platform: Platform;
15	  detected: boolean;
16	  skillDir: string;
17	  exists: boolean;
18	  writable?: boolean;
19	}
20	
21	/**
22	 * Platform configuration — where each platform stores skills.
23	 */
24	const PLATFORM_DIRS: Record<Platform, string> = {
25	  claude: resolve(homedir(), ".claude/skills"),
26	  opencode: resolve(homedir(), ".config/opencode/skill"),
27	  codex: resolve(homedir(), ".codex/skills"),
28	};
29	
30	/**
31	 * Platform detection indicators — directories that suggest a platform is in use.
32	 */
33	const PLATFORM_INDICATORS: Record<Platform, string[]> = {
34	  claude: [resolve(homedir(), ".claude")],
35	  opencode: [resolve(homedir(), ".config/opencode")],
36	  codex: [resolve(homedir(), ".codex")],
37	};
38	
39	/**
40	 * Detect which AI platforms are available on this system.
41	 */
42	export function detectPlatforms(): PlatformInfo[] {
43	  const results: PlatformInfo[] = [];
44	
45	  for (const platform of Object.keys(PLATFORM_DIRS) as Platform[]) {
46	    const skillDir = PLATFORM_DIRS[platform];
47	    const indicators = PLATFORM_INDICATORS[platform];
48	    const detected = indicators.some((dir) => existsSync(dir));
49	    const dirExists = existsSync(skillDir);
50	
51	    results.push({
52	      platform,
53	      detected,
54	      skillDir,
55	      exists: dirExists,
56	    });
57	  }
58	
59	  return results;
60	}
61	
62	/**
63	 * Get the skill directory path for a specific platform.
64	 */
65	export function getSkillDir(platform: Platform): string {
66	  return PLATFORM_DIRS[platform];
67	}
68	
69	/**
70	 * Get all platform skill directory paths.
71	 */
72	export function getAllSkillDirs(): Record<Platform, string> {
73	  return { ...PLATFORM_DIRS };
74	}
